function runSchemaVariant(value, mutateSchema) { const root = mkdtempSync(join(tmpdir(), "hospital-workspace-evidence-schema-")); const manifestPath = join(root, "manifest.json"); const schemaPath = join(root, "schema.json"); const schemaCopy = JSON.parse(readFileSync(schema, "utf8")); mutateSchema(schemaCopy); writeFileSync(manifestPath, `${JSON.stringify(value)}\n`); writeFileSync(schemaPath, `${JSON.stringify(schemaCopy)}\n`); try { return spawnSync(process.execPath, [checker, "--schema", schemaPath, "--manifest", manifestPath], { cwd: root, encoding: "utf8", env: checkerEnvironment({ mode: "LOCAL" }) }); } finally { rmSync(root, { recursive: true, force: true }); } }
