test("[CI] trusted rehearsal inputs reject malformed, mismatched, and required NOT_APPLICABLE declarations", () => { const repository = boundRepository(); try { const bindings = ["--ci", "--expected-source-commit", repository.sourceCommit, "--expected-result-commit", repository.resultCommit, "--expected-result-tree", repository.resultTree]; const ci = syntheticCiOverrides(repository.resultCommit); let output = runCi(withBindings(repository), [...bindings, "--expected-rollback-rehearsal", "maybe", "--expected-recovery-rehearsal", "not-required"], repository.root, ci); assertFailure(output, ["INVALID_TRUSTED_REHEARSAL_EXPECTATION", "TRUSTED_REHEARSAL_EXPECTATION_REQUIRED"], { exactRules: ["INVALID_TRUSTED_REHEARSAL_EXPECTATION", "TRUSTED_REHEARSAL_EXPECTATION_REQUIRED"], permitCiFindings: true }); const mismatch = withBindings(repository, { rollback: evidence("PASS"), recovery: evidence("PASS") }); output = runCi(mismatch, [...bindings, "--expected-rollback-rehearsal", "required", "--expected-recovery-rehearsal", "not-required"], repository.root, ci); assertFailure(output, "TRUSTED_REHEARSAL_EXPECTATION_MISMATCH", { exactRules: ["TRUSTED_REHEARSAL_EXPECTATION_MISMATCH"] }); const sol = receipt("sol_acceptance", "ACCEPT", { sourceCommit: repository.sourceCommit, resultCommit: repository.resultCommit, resultTree: repository.resultTree, reviewedDiffBase: repository.sourceCommit, reviewedDiffHead: repository.resultCommit }); const required = withBindings(repository, { risk: "high", acceptanceTier: "sol-acceptance", rehearsalRequirements: { rollback: true, recovery: false }, rollback: evidence("NOT_APPLICABLE"), recovery: evidence("PASS"), requiredReviewAgents: [{ agent: "terra_reviewer", outcome: "APPROVED" }, { agent: "sol_acceptance", outcome: "ACCEPT" }], reviewReceipts: [withBindings(repository).reviewReceipts[0], sol] }); output = runCi(required, [...bindings, "--expected-rollback-rehearsal", "required", "--expected-recovery-rehearsal", "not-required"], repository.root, ci); assertFailure(output, "NOT_APPLICABLE_REHEARSAL_NOT_PERMITTED", { exactRules: ["EVIDENCE_INSTANCE_SCHEMA_INVALID", "NOT_APPLICABLE_REHEARSAL_NOT_PERMITTED"] }); } finally { rmSync(repository.root, { recursive: true, force: true }); } });
