test("[CI] trusted binding rejects a missing result commit and a mismatched commit tree", () => { const repository = boundRepository(); try { const missing = "f".repeat(40); const missingBindings = { ...repository, resultCommit: missing }; const rehearsal = ["--expected-rollback-rehearsal", "not-required", "--expected-recovery-rehearsal", "not-required"]; let output = runCi(withBindings(missingBindings), ["--ci", "--expected-source-commit", repository.sourceCommit, "--expected-result-commit", missing, "--expected-result-tree", repository.resultTree, ...rehearsal], repository.root, syntheticCiOverrides(missing)); assertFailure(output, "RESULT_COMMIT_GIT_OBJECT_MISSING", { exactRules: ["RESULT_COMMIT_GIT_OBJECT_MISSING"] }); const wrongTree = { ...repository, resultTree: repository.sourceTree }; output = runCi(withBindings(wrongTree), ["--ci", "--expected-source-commit", repository.sourceCommit, "--expected-result-commit", repository.resultCommit, "--expected-result-tree", repository.sourceTree, ...rehearsal], repository.root, syntheticCiOverrides(repository.resultCommit)); assertFailure(output, "RESULT_COMMIT_TREE_MISMATCH", { exactRules: ["RESULT_COMMIT_TREE_MISMATCH"] }); } finally { rmSync(repository.root, { recursive: true, force: true }); } });
