function assertRejected(output) { assert.notEqual(output.status, 0, output.stdout); const parsed = report(output); assert.equal(parsed.status, "FAIL", output.stdout); assert.ok(parsed.findings.length > 0, output.stdout); assert.ok(parsed.findings.every((finding) => ["path,rule", "instancePath,keyword,rule,schemaPath"].includes(Object.keys(finding).sort().join(","))), output.stdout); return parsed; }
