test("PASS and task CONDITIONAL reject undeclared phase-gate conditional recommendations", () => { const optionalPhaseRecommendation = receipt("sol_phase_gate", "CONDITIONAL_RECOMMENDED", { reviewType: "phase-gate" }); assertFailure(runLocal(base({ reviewReceipts: [receipt(), optionalPhaseRecommendation] })), "PASS_HAS_NEGATIVE_REVIEW_OUTCOME", { exactRules: ["PASS_HAS_NEGATIVE_REVIEW_OUTCOME"] }); assertFailure(runLocal(base({ decision: "CONDITIONAL", reviewReceipts: [receipt(), optionalPhaseRecommendation] })), "CONDITIONAL_HAS_NEGATIVE_REVIEW_OUTCOME", { exactRules: ["CONDITIONAL_HAS_NEGATIVE_REVIEW_OUTCOME"] }); });
