function assertSchemaFinding(output, rule) { const parsed = assertRejected(output); const schemaFindings = parsed.findings.filter((finding) => finding.rule === rule); assert.ok(schemaFindings.length > 0, output.stdout); for (const finding of schemaFindings) { assert.deepEqual(Object.keys(finding).sort(), ["instancePath", "keyword", "rule", "schemaPath"]); assert.doesNotMatch(JSON.stringify(finding), /Synthetic fixture|abcdefgh|hospital-workspace\.evidence\.v3/i); } return parsed; }
test("standards-compliant validator accepts the complete Draft 2020-12 schema and example", () => { assertPass(runSchemaVariant(base(), () => {})); });
for (const [name, mutate, rule] of [["missing reviewReceipt definition", (candidate) => { delete candidate.$defs.reviewReceipt; }, "JSON_SCHEMA_COMPILE_ERROR"], ["unresolved reference", (candidate) => { candidate.properties.reviewReceipts.items.$ref = "#/$defs/missingReviewReceipt"; }, "JSON_SCHEMA_COMPILE_ERROR"], ["invalid keyword type", (candidate) => { candidate.properties.branch.type = { invalid: true }; }, "JSON_SCHEMA_META_INVALID"], ["invalid root required definition", (candidate) => { candidate.required = "schemaVersion"; }, "JSON_SCHEMA_META_INVALID"]]) test(`schema ${name} fails closed`, () => { assertSchemaFinding(runSchemaVariant(base(), mutate), rule); });
test("schema example missing required field fails instance validation", () => { const candidate = base(); delete candidate.program; assertSchemaFinding(runSchemaVariant(candidate, () => {}), "EVIDENCE_INSTANCE_SCHEMA_INVALID"); });
test("schema example invalid enum fails instance validation", () => { assertSchemaFinding(runSchemaVariant(base({ risk: "unsupported" }), () => {}), "EVIDENCE_INSTANCE_SCHEMA_INVALID"); });
test("schema example wrong agent/outcome pair fails instance validation", () => { assertSchemaFinding(runSchemaVariant(base({ reviewReceipts: [receipt("terra_reviewer", "ACCEPT")] }), () => {}), "EVIDENCE_INSTANCE_SCHEMA_INVALID"); });
test("schema example malformed date-time fails instance validation", () => { assertSchemaFinding(runSchemaVariant(base({ decidedAt: "2026-08-31" }), () => {}), "EVIDENCE_INSTANCE_SCHEMA_INVALID"); });
test("schema compile exception fails closed with sanitized schema findings", () => { assertSchemaFinding(runSchemaVariant(base(), (candidate) => { candidate.$defs.reviewReceipt = { type: "string", allOf: [{ $ref: "#/$defs/does-not-exist" }] }; }), "JSON_SCHEMA_COMPILE_ERROR"); });

test("PASS accepts the required Terra reviewer with its configured model", () => { assertPass(runLocal(base({ reviewReceipts: [receipt("terra_reviewer", "APPROVED", { model: "gpt-5.6-terra" })] }))); });
test("critical PASS accepts Terra security and Sol architecture-security with configured models", () => { const manifest = base({ risk: "critical", acceptanceTier: "sol-architecture-security", rollback: evidence("PASS"), recovery: evidence("PASS"), requiredReviewAgents: [{ agent: "terra_reviewer", outcome: "APPROVED" }, { agent: "terra_security", outcome: "APPROVED" }, { agent: "sol_architecture_security", outcome: "ACCEPT" }], reviewReceipts: [receipt("terra_reviewer"), receipt("terra_security", "APPROVED", { reviewType: "security" }), receipt("sol_architecture_security", "ACCEPT", { reviewType: "architecture-security" })] }); assertPass(runLocal(manifest)); });
test("phase PASS accepts Sol phase-gate PASS_RECOMMENDED with its configured model", () => { const manifest = base({ scope: { kind: "phase", phaseId: "HW-00", taskId: null }, acceptanceTier: "sol-phase-gate", requiredReviewAgents: [{ agent: "terra_reviewer", outcome: "APPROVED" }, { agent: "terra_security", outcome: "APPROVED" }, { agent: "sol_phase_gate", outcome: "PASS_RECOMMENDED" }], reviewReceipts: [receipt("terra_reviewer"), receipt("terra_security", "APPROVED", { reviewType: "security" }), receipt("sol_phase_gate", "PASS_RECOMMENDED", { reviewType: "phase-gate" })] }); assertPass(runLocal(manifest)); });
test("BLOCKED accepts empty reviewReceipts when a declared required review is absent", () => { const manifest = base({ decision: "BLOCKED", requiredReviewAgents: [{ agent: "terra_reviewer", outcome: "APPROVED" }, { agent: "terra_security", outcome: "APPROVED" }], reviewReceipts: [] }); assertPass(runLocal(manifest)); });
test("BLOCKED preserves valid negative Terra and Sol receipts", () => { const terra = base({ decision: "BLOCKED", reviewReceipts: [receipt("terra_reviewer", "CHANGES_REQUESTED")] }); assertPass(runLocal(terra)); const sol = base({ decision: "BLOCKED", risk: "high", acceptanceTier: "sol-acceptance", requiredReviewAgents: [{ agent: "terra_reviewer", outcome: "APPROVED" }, { agent: "sol_acceptance", outcome: "ACCEPT" }], reviewReceipts: [receipt("terra_reviewer"), receipt("sol_acceptance", "BLOCKED", { reviewType: "acceptance" })] }); assertPass(runLocal(sol)); });
test("wrong reviewer models fail closed and do not satisfy PASS or CONDITIONAL", () => { const cases = [["sol_acceptance", "gpt-5.6-terra", "ACCEPT"], ["sol_architecture_security", "gpt-5.6-terra", "ACCEPT"], ["sol_phase_gate", "gpt-5.6-terra", "PASS_RECOMMENDED"], ["terra_reviewer", "gpt-5.6-sol", "APPROVED"], ["terra_security", "gpt-5.6-sol", "APPROVED"], ["terra_reviewer", "gpt-5.6-terra-alias", "APPROVED"], ["terra_reviewer", "GPT-5.6-TERRA", "APPROVED"], ["terra_reviewer", " gpt-5.6-terra", "APPROVED"], ["terra_reviewer", "gpt-5.6-terra ", "APPROVED"], ["terra_reviewer", "", "APPROVED"]]; const withoutSchemaModelConstraints = (candidate) => { for (const clause of candidate.$defs.reviewReceipt.allOf) delete clause.then.properties.model; }; for (const [agent, model, outcome] of cases) { const reviewType = agent.startsWith("sol_") ? (agent === "sol_phase_gate" ? "phase-gate" : "acceptance") : "implementation"; const requiredOutcome = agent === "sol_phase_gate" ? "PASS_RECOMMENDED" : agent.startsWith("sol_") ? "ACCEPT" : "APPROVED"; const receiptValue = receipt(agent, outcome, { model, reviewType }); const manifest = base({ requiredReviewAgents: [{ agent, outcome: requiredOutcome }], reviewReceipts: [receiptValue] }); const parsed = assertRejected(runLocal(manifest)); assert.ok(parsed.findings.some((finding) => finding.rule === "EVIDENCE_INSTANCE_SCHEMA_INVALID" || finding.rule === "INVALID_REVIEW_RECEIPT_SCHEMA"), `${agent}/${model}: ${JSON.stringify(parsed)}`); if (model) { const semantic = assertRejected(runSchemaVariant(manifest, withoutSchemaModelConstraints)); assert.ok(semantic.findings.some((finding) => finding.rule === "REVIEW_MODEL_MISMATCH"), `${agent}/${model}: ${JSON.stringify(semantic)}`); assert.ok(semantic.findings.some((finding) => finding.rule === "MISSING_REQUIRED_REVIEW_RECEIPT"), `${agent}/${model}: ${JSON.stringify(semantic)}`); const conditional = base({ decision: "CONDITIONAL", requiredReviewAgents: [{ agent, outcome: requiredOutcome }], reviewReceipts: [receiptValue] }); const conditionalParsed = assertRejected(runSchemaVariant(conditional, withoutSchemaModelConstraints)); assert.ok(conditionalParsed.findings.some((finding) => finding.rule === "REVIEW_MODEL_MISMATCH"), `${agent}/${model}: ${JSON.stringify(conditionalParsed)}`); } } });
test("wrong-model positive receipt remains a genuine blocker without being counted", () => { const manifest = base({ decision: "BLOCKED", reviewReceipts: [receipt("terra_reviewer", "APPROVED", { model: "gpt-5.6-sol" })] }); const parsed = assertRejected(runLocal(manifest)); assert.ok(parsed.findings.some((finding) => finding.rule === "REVIEW_MODEL_MISMATCH"), JSON.stringify(parsed)); });
test("Schema and semantic validation both reject a wrong model", () => { const manifest = base({ reviewReceipts: [receipt("terra_reviewer", "APPROVED", { model: "gpt-5.6-sol" })] }); const direct = assertRejected(runLocal(manifest)); assert.ok(direct.findings.some((finding) => finding.rule === "REVIEW_MODEL_MISMATCH"), JSON.stringify(direct)); const schemaOnly = assertSchemaFinding(runSchemaVariant(manifest, () => {}), "EVIDENCE_INSTANCE_SCHEMA_INVALID"); assert.ok(schemaOnly.findings.some((finding) => finding.rule === "EVIDENCE_INSTANCE_SCHEMA_INVALID"), JSON.stringify(schemaOnly)); });
test("PASS and CONDITIONAL reject empty reviewReceipts", () => { for (const decision of ["PASS", "CONDITIONAL"]) assertRejected(runLocal(base({ decision, reviewReceipts: [] }))); });
test("PASS and CONDITIONAL reject one missing declared required review", () => { const requiredReviewAgents = [{ agent: "terra_reviewer", outcome: "APPROVED" }, { agent: "terra_security", outcome: "APPROVED" }]; const receipts = [receipt("terra_reviewer")]; for (const decision of ["PASS", "CONDITIONAL"]) { const parsed = assertRejected(runLocal(base({ decision, requiredReviewAgents, reviewReceipts: receipts }))); assert.ok(parsed.findings.some((finding) => finding.rule === "MISSING_REQUIRED_REVIEW_RECEIPT"), JSON.stringify(parsed)); } });
test("unknown model and explicit model alias are rejected as distinct fixtures", () => { for (const model of ["model.unknown.synthetic", "gpt-5.6-terra-alias"]) { const parsed = assertRejected(runLocal(base({ reviewReceipts: [receipt("terra_reviewer", "APPROVED", { model })] }))); assert.ok(parsed.findings.some((finding) => finding.rule === "EVIDENCE_INSTANCE_SCHEMA_INVALID" || finding.rule === "INVALID_REVIEW_RECEIPT_SCHEMA"), JSON.stringify(parsed)); } });
